const CACHE='terra-atlas-v1.0.0';
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['./','index.html','style.css','app.js','data.js','globe.js','vendor/three.module.js','vendor/three.core.js','vendor/OrbitControls.js','offline-files.json'])).then(()=>self.skipWaiting()));});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('terra-atlas-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',e=>{const r=e.request,u=new URL(r.url);if(r.method!=='GET'||u.origin!==self.location.origin)return;e.respondWith((async()=>{const cache=await caches.open(CACHE);try{const response=await fetch(r);if(response.ok&&!response.redirected&&!u.pathname.includes('/api/'))await cache.put(r,response.clone());return response;}catch{const stored=await cache.match(r);if(stored)return stored;if(r.mode==='navigate')return(await cache.match('index.html'))||Response.error();return Response.error();}})());});
self.addEventListener('message',e=>{if(e.data?.type!=='CACHE_ALL')return;const port=e.ports[0];e.waitUntil((async()=>{try{const files=await(await fetch('offline-files.json')).json(),cache=await caches.open(CACHE);let done=0;for(const file of files){const url=new URL(file,self.location.href);const response=await fetch(url,{cache:'reload'});if(!response.ok||response.redirected)throw Error('Eine Atlasdatei konnte nicht gespeichert werden.');await cache.put(url,response);port?.postMessage({type:'progress',done:++done,total:files.length});}port?.postMessage({type:'done'});}catch(err){port?.postMessage({type:'error',message:err.message||'Offline-Speichern fehlgeschlagen.'});}})());});
